//! Reads and writes the layout declarations that users can edit in Rex's generated files.

use std::fmt::Write as _;
use std::path::Path;

pub(super) const GENERATED: &str = "-- Generated by milo setup.\n";

const START_LISTENER: &str = "\n-- During a syntax check or a one-off layout, do not start a listener.\n\
    if not rex.args and not os.getenv(\"MILO_CHECKING_REX\") then\n  \
    rex.exec.start({ milo, \"listen\" }, { detach = true })\nend\n";
const ACTIONS: &str = include_str!("actions.lua");
const LISTENER: &str = include_str!("listener.lua");

/// Match whole shipped templates, including the last one, without keeping a
/// second copy of the old Lua or treating any custom code as ours.
fn fingerprint(text: &str) -> u64 {
    text.bytes().fold(0xcbf2_9ce4_8422_2325, |hash, byte| (hash ^ u64::from(byte)).wrapping_mul(0x0100_0000_01b3))
}

struct Declarations<'a> {
    values: [&'a str; 4],
    panes: [Option<&'a str>; 3],
    insert_panes: usize,
    executable: Option<&'a str>,
}

impl Declarations<'_> {
    fn layout(&self) -> Option<Layout> {
        let [width, outline_share, rows, new_tabs] = self.values;
        for text in [width, outline_share] {
            let number = text.parse::<f64>().ok()?;
            if !(0.0 < number && number < 1.0) {
                return None;
            }
        }
        rows.parse::<u32>().ok().filter(|&rows| rows > 0)?;
        let mut panes = [false; 3];
        for (pane, value) in panes.iter_mut().zip(self.panes) {
            if let Some(value) = value {
                *pane = value.parse().ok()?;
            }
        }
        Some(Layout {
            width: width.into(),
            outline_share: outline_share.into(),
            usage_rows: rows.into(),
            new_tabs: new_tabs.parse().ok()?,
            panes,
        })
    }
}
/// Named panes keep Lua and the on-screen choices in the same order.
#[derive(Clone, Copy, PartialEq, Eq)]
pub(super) enum TabPane {
    Outline,
    History,
    Usage,
}

impl TabPane {
    pub const ALL: [Self; 3] = [Self::Outline, Self::History, Self::Usage];

    pub const fn name(self) -> &'static str {
        match self {
            Self::Outline => "outline",
            Self::History => "history",
            Self::Usage => "usage",
        }
    }
}

/// The label, Lua proportion and preview width of a preset belong together.
#[derive(Clone, Copy)]
pub(super) struct Width {
    name: &'static str,
    pub proportion: &'static str,
    sketch: usize,
}

pub(super) const WIDTHS: [Width; 3] = [
    Width { name: "Thin", proportion: "0.22", sketch: 9 },
    Width { name: "Medium", proportion: "0.30", sketch: 12 },
    Width { name: "Wide", proportion: "0.38", sketch: 15 },
];

/// Display names are fixed; a proportion set by hand is kept until the user changes it here.
#[derive(Clone, PartialEq, Eq)]
pub(super) struct Layout {
    pub panes: [bool; 3],
    pub new_tabs: bool,
    pub width: String,
    pub outline_share: String,
    pub usage_rows: String,
}

impl Default for Layout {
    fn default() -> Self {
        Self {
            panes: [true; 3],
            new_tabs: false,
            width: WIDTHS[0].proportion.into(),
            outline_share: "0.70".into(),
            usage_rows: "5".into(),
        }
    }
}

impl Layout {
    /// Only these choices can affect either the current tab or a future one.
    pub fn enabled(&self) -> bool {
        self.new_tabs || self.panes.contains(&true)
    }

    pub fn chosen(&self, pane: TabPane) -> bool {
        self.panes[pane as usize]
    }

    pub fn toggle(&mut self, pane: TabPane) {
        self.panes[pane as usize] = !self.chosen(pane);
    }

    /// Only exact presets get a preset label, even if a hand edit is close.
    pub fn width_name(&self) -> &'static str {
        self.preset().map_or("Custom", |width| width.name)
    }

    /// A hand-edited width still gets a readable preview.
    pub fn sketch_width(&self) -> usize {
        self.preset().map_or(12, |width| width.sketch)
    }

    fn preset(&self) -> Option<Width> {
        WIDTHS.into_iter().find(|width| width.proportion == self.width)
    }

    /// Pressing change after a custom width starts the normal cycle again.
    pub fn next_width(&mut self) {
        let next = WIDTHS.iter().skip_while(|width| width.proportion != self.width).nth(1).unwrap_or(&WIDTHS[0]);
        self.width.clear();
        self.width.push_str(next.proportion);
    }

    /// Read the layout values without rewriting the rest of the user's Lua.
    pub(super) fn parse(text: &str) -> Option<Self> {
        declarations(text)?.layout()
    }
}

fn declarations(text: &str) -> Option<Declarations<'_>> {
    let mut lines = text.lines();
    if lines.next()?.trim_end() != GENERATED.trim_end() {
        return None;
    }
    let mut comment = None;
    let mut lines = lines.map(move |line| lua_code(line, &mut comment)).filter(|line| !line.is_empty());
    let mut values = [None; 4];
    let mut insert_panes = None;
    for line in lines.by_ref() {
        let Some((key, value)) = line.split_once('=') else { continue };
        let (key, value) = (key.trim_end(), value.trim());
        match key {
            "local column_width" => values[0] = Some(value),
            "local outline_share" => values[1] = Some(value),
            "local usage_rows" => values[2] = Some(value),
            "local arrange_new_tabs" => values[3] = Some(value),
            "local chosen" if value == "{" => {
                let start = value.as_ptr().addr() - text.as_ptr().addr();
                insert_panes = text[start..].find('\n').map(|end| start + end + 1);
                break;
            }
            _ => {}
        }
    }
    let [Some(width), Some(outline), Some(rows), Some(new_tabs)] = values else { return None };
    let insert_panes = insert_panes?;
    let mut panes = [None; 3];
    for line in lines.by_ref() {
        if line == "}" {
            let executable = lines.take_while(|line| !line.starts_with("local terminal")).find_map(|line| {
                let (key, value) = line.split_once('=')?;
                (key.trim_end() == "local milo").then(|| value.trim())
            });
            return Some(Declarations { values: [width, outline, rows, new_tabs], panes, insert_panes, executable });
        }
        if let Some((key, value)) = line.split_once('=')
            && let Some(pane) = TabPane::ALL.into_iter().find(|pane| pane.name() == key.trim_end())
        {
            panes[pane as usize] = Some(value.trim().trim_end_matches([',', ';']).trim_end());
        }
    }
    None
}

/// The layout's declarations are one per line, with optional Lua comments.
fn lua_code<'a>(mut line: &'a str, comment: &mut Option<usize>) -> &'a str {
    if let Some(depth) = *comment {
        let Some(tail) = comment_tail(line, depth) else { return "" };
        *comment = None;
        line = tail;
    }
    loop {
        // The executable is the only quoted declaration. Dashes in its
        // path are not the start of a Lua comment.
        if let Some(rest) = line.trim_start().strip_prefix("local milo")
            && let Some(literal) = rest.trim_start().strip_prefix('=').map(str::trim_start)
            && let Some(end) = lua_string_end(literal)
        {
            let end = literal.as_ptr().addr() - line.as_ptr().addr() + end;
            return line[..end].trim();
        }
        let Some((code, rest)) = line.split_once("--") else { return line.trim() };
        let code = code.trim();
        let Some((depth, rest)) = long_bracket(rest, '[') else { return code };
        let tail = comment_tail(rest, depth);
        *comment = tail.is_none().then_some(depth);
        if let Some(tail) = tail
            && code.is_empty()
        {
            line = tail;
        } else {
            return code;
        }
    }
}

fn lua_string_end(text: &str) -> Option<usize> {
    let mut escaped = false;
    for (i, byte) in text.strip_prefix('"')?.bytes().enumerate() {
        if escaped {
            escaped = false;
        } else if byte == b'"' {
            return Some(i + 2);
        } else {
            escaped = byte == b'\\';
        }
    }
    None
}

fn comment_tail(line: &str, depth: usize) -> Option<&str> {
    line.match_indices(']').find_map(|(i, _)| {
        let (end, tail) = long_bracket(&line[i..], ']')?;
        (depth == end).then_some(tail)
    })
}

fn long_bracket(text: &str, bracket: char) -> Option<(usize, &str)> {
    let text = text.strip_prefix(bracket)?;
    let rest = text.trim_start_matches('=');
    Some((text.len() - rest.len(), rest.strip_prefix(bracket)?))
}

/// A path in a Lua 5.1 string, even if some of its bytes are not UTF-8.
pub(super) fn lua_path(path: &Path) -> String {
    let mut literal = String::from("\"");
    for &byte in path.as_os_str().as_encoded_bytes() {
        match byte {
            b'"' | b'\\' => literal.extend(['\\', char::from(byte)]),
            b' '..=b'~' => literal.push(char::from(byte)),
            _ => write!(literal, "\\{byte:03}").expect("writing to a string"),
        }
    }
    literal.push('"');
    literal
}

/// Edit just the layout values of a hand-edited file; its action code and comments stay put.
pub(super) fn update_actions(text: &str, layout: &Layout, executable: &Path) -> Option<Option<String>> {
    let fields = declarations(text)?;
    let old = fields.layout()?;
    if fields.executable.is_some_and(|previous| shipped_actions(text, &old, previous)) {
        let generated = rex_lua(layout, executable);
        return Some((generated != text).then_some(generated));
    }
    if old == *layout {
        return Some(None);
    }

    let mut edits = Vec::new();
    let mut replace = |before: &str, after: &str| {
        if before != after {
            // The declarations are slices of the input, including any leading indentation.
            let start = before.as_ptr().addr() - text.as_ptr().addr();
            edits.push((start..start + before.len(), after.to_owned()));
        }
    };
    let values = [
        layout.width.as_str(),
        &layout.outline_share,
        &layout.usage_rows,
        if layout.new_tabs { "true" } else { "false" },
    ];
    for (before, after) in fields.values.into_iter().zip(values) {
        replace(before, after);
    }
    let newline = if text.as_bytes().contains(&b'\r') && text.contains("\r\n") { "\r\n" } else { "\n" };
    let mut added = String::new();
    for (pane, before) in TabPane::ALL.into_iter().zip(fields.panes) {
        let chosen = layout.chosen(pane);
        if let Some(before) = before {
            replace(before, if chosen { "true" } else { "false" });
        } else if chosen {
            write!(added, "  {} = true,{newline}", pane.name()).expect("writing to a string");
        }
    }
    let start = fields.insert_panes;
    if !added.is_empty() {
        edits.push((start..start, added));
    }
    edits.sort_unstable_by_key(|(range, _)| range.start);
    let mut updated = text.to_owned();
    for (range, value) in edits.into_iter().rev() {
        updated.replace_range(range, &value);
    }
    if old.new_tabs != layout.new_tabs {
        let footer = if newline == "\n" { START_LISTENER.into() } else { START_LISTENER.replace('\n', newline) };
        if layout.new_tabs && !updated.ends_with(&footer) {
            updated.push_str(&footer);
        } else if !layout.new_tabs && updated.ends_with(&footer) {
            updated.truncate(updated.len() - footer.len());
        }
    }
    Some(Some(updated))
}

pub(super) fn owns_actions(text: &str) -> bool {
    declarations(text).is_some_and(|fields| {
        fields.layout().zip(fields.executable).is_some_and(|(layout, exe)| shipped_actions(text, &layout, exe))
    })
}

fn shipped_actions(text: &str, layout: &Layout, exe: &str) -> bool {
    let prefix = actions_prefix(layout, exe);
    let Some(mut body) = text.strip_prefix(&prefix) else { return false };
    if layout.new_tabs {
        let Some(code) = body.strip_suffix(START_LISTENER) else { return false };
        body = code;
    }
    body == ACTIONS || fingerprint(body) == 0x560c_5b9a_caa8_625d
}

/// The installed and temporary layouts must run exactly the same actions.
pub(super) fn rex_lua(layout: &Layout, executable: &Path) -> String {
    let mut lua = actions_prefix(layout, &lua_path(executable));
    lua.push_str(ACTIONS);
    if layout.new_tabs {
        lua.push_str(START_LISTENER);
    }
    lua
}

fn actions_prefix(layout: &Layout, executable: &str) -> String {
    let mut lua = format!(
        "{GENERATED}\n-- Fraction of the tab for the left column.\nlocal column_width = {}\n\
         -- Fraction of that column for the outline when history is below it.\nlocal outline_share = {}\n\
         -- Terminal rows for the usage strip.\nlocal usage_rows = {}\n\
         -- Whether Rex arranges each new shell tab.\nlocal arrange_new_tabs = {}\n\n\
         -- The panes included by Milo: Arrange This Tab.\nlocal chosen = {{\n",
        layout.width, layout.outline_share, layout.usage_rows, layout.new_tabs,
    );
    for pane in TabPane::ALL {
        if layout.chosen(pane) {
            writeln!(lua, "  {} = true,", pane.name()).expect("writing to a string");
        }
    }
    lua.push_str("}\n\n");
    writeln!(lua, "local milo = {executable}\n").expect("writing to a string");
    lua
}

/// The listener reuses the installed actions rather than embedding another copy.
pub(super) fn listener_lua(rex_file: &Path) -> String {
    format!("{}{LISTENER}", listener_prefix(rex_file))
}

fn listener_prefix(rex_file: &Path) -> String {
    format!(
        "{GENERATED}-- Used by milo listen to arrange newly opened shell tabs.\nlocal rex_config = {}\n\n",
        lua_path(rex_file),
    )
}

pub(super) fn owns_listener(text: &str, rex_file: &Path) -> bool {
    text.strip_prefix(&listener_prefix(rex_file))
        .is_some_and(|body| body == LISTENER || fingerprint(body) == 0x18ff_d6b9_f7bd_6f63)
}
